building(-12,-4,6,5,'#e8d7af','#8f9c71');building(-23,2,4.5,4,'#e2d5b0','#a4ac7c');building(-18,-20,5,4,'#e5d7b8','#8c9f70');building(16,-10,8,6,'#e8e4ce','#7a9c90','lab');building(24,17,6,5,'#dfd2b0','#a5aa7b');
