for(let i=0;i<80;i++){const x=rand()*64-32,z=rand()*52-26;if(Math.abs(x-5)<4)continue;box(.15,.4,.15,'#82965e',x,.5,z);box(.4,.18,.4,i%3===0?'#e6cc76':'#f3e5bc',x,.8,z)}
for(let i=0;i<22;i++){let x=rand()*62-31,z=rand()*50-25;if(Math.abs(x-5)<4)continue;const m=box(.7+rand(),.6+rand()*.8,.8,'#a4b19a',x,.6,z);m.rotation.y=rand()*2}
box(5,.1,5,'#d9d2ae',0,.4,10);box(1.1,1.3,1.1,'#a8b993',-1,1,10);box(1.9,.25,1.9,'#d9d9b2',-1,1.8,10);cone(.7,1.3,'#b5cc83',-1,2.5,10,4);
const player=new T.Group();scene.add(player);const body=box(.8,1,.48,'#ebc15f',0,1.5,0,player);box(.7,.7,.66,'#edc9a0',0,2.35,0,player);box(.77,.22,.7,'#5b7252',0,2.75,0,player);box(.9,.12,.85,'#5b7252',0,2.67,.1,player);box(.52,.65,.2,'#7c9170',0,1.5,-.35,player);const limbs=[];for(const s of [-1,1]){limbs.push(box(.28,.8,.3,'#65858b',s*.23,.63,0,player));limbs.push(box(.25,.85,.3,'#ebc15f',s*.57,1.52,0,player));box(.09,.09,.03,'#394e40',s*.17,2.4,.35,player)}
player.position.set(0,.45,9);
const tokens=new Map();const collected=new Set();const ringMat=new T.MeshBasicMaterial({color:'#fff0a1',transparent:true,opacity:.6,side:T.DoubleSide});
