window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright',' '].includes(e.key.toLowerCase()))e.preventDefault();keys.add(e.key.toLowerCase())});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>keys.clear());
return {start(){active=true},pause(v){paused=v;keys.clear()},setKey(k,on){on?keys.add(k):keys.delete(k)},collect(id){collected.add(id);tokens.get(id)?.g.removeFromParent();near=null;onNear(null)},setCollected(ids){collected.clear();for(const [id,t] of tokens){if(ids.includes(id)){collected.add(id);t.g.removeFromParent()}else if(!t.g.parent)scene.add(t.g)}},restore(pos){if(pos&&Number.isFinite(pos.x)&&Number.isFinite(pos.z)&&!blocked(pos.x,pos.z))player.position.set(pos.x,.45,pos.z)},position(){return {x:player.position.x,z:player.position.z}},nearest(){return near},night(v){scene.background=new T.Color(v?'#8fa5ab':'#d7e4d2');sun.intensity=v?1:3;ambient.intensity=v?1.6:2.6}};
